func total(_ prices: [Double]) -> Double {
    prices.reduce(0, +)
}
print(total([10, 20]))

struct Pricing {   // math only
    func sum(_ p: [Double]) -> Double {
        p.reduce(0, +)
    }
}
print(Pricing().sum([10, 20]))

import Foundation
func label(_ total: Double) -> String {
    "Total: $" + String(format: "%.2f", total)
}
print(label(30))

